package org.opensourcepingpong.competition;
import org.opensourcepingpong.common.api.BusinessException; import org.springframework.http.HttpStatus;
public final class CompetitionStateMachine {private CompetitionStateMachine(){} public static CompetitionStatus next(CompetitionStatus from,String action){CompetitionStatus target=switch(action){case "publish"->CompetitionStatus.REGISTRATION;case "close"->CompetitionStatus.ARRANGING;case "ready"->CompetitionStatus.READY;case "start"->CompetitionStatus.RUNNING;case "confirm"->CompetitionStatus.RESULT_CONFIRMING;case "finalize"->CompetitionStatus.FINISHED;case "cancel"->CompetitionStatus.CANCELLED;default->throw invalid();};if(from==CompetitionStatus.FINISHED||from==CompetitionStatus.CANCELLED||!(target==CompetitionStatus.CANCELLED||target.ordinal()==from.ordinal()+1))throw invalid();return target;}private static BusinessException invalid(){return new BusinessException(HttpStatus.CONFLICT,"COMPETITION_INVALID_STATE","比赛状态不允许该操作");}}
